104	/// Places that bind a pending collection directive, in document order:
105	/// (line, collection key, is sequence). Every sequence item binds its sequence;
106	/// a mapping entry binds its collection value.
107	fn dir_anchors(n: &parser::Node, ls: &[usize], out: &mut Vec<(usize, usize, bool)>) {
108	    use parser::Kind;
109	    match &n.kind {
110	        Kind::Map(es) => {
111	            for e in es {
112	                let v = &e.value;
113	                if matches!(v.kind, Kind::Map(_) | Kind::Seq(_) | Kind::FlowMap(_) | Kind::FlowSeq(_)) {
114	                    out.push((e.line, coll_key(v, ls), matches!(v.kind, Kind::Seq(_) | Kind::FlowSeq(_))));
115	                }
116	                dir_anchors(v, ls, out);
117	            }
118	        }
119	        Kind::Seq(items) => {
120	            let k = coll_key(n, ls);
121	            for it in items {
122	                out.push((it.line, k, true));
123	                dir_anchors(&it.value, ls, out);
124	            }
125	        }
126	        Kind::FlowSeq(_) => out.push((n.line, n.start, true)),
127	        _ => {}
128	    }
129	}

